static void write_all(int fd, const void *buffer, size_t length)
{
    const char *p = buffer;

    while (length > 0) {
        ssize_t written = write(fd, p, length);

        if (written < 0) {
            if (errno == EINTR)
                continue;
            die("write");
        }
        if (written == 0) {
            errno = EIO;
            die("write");
        }

        p += written;
        length -= (size_t)written;
    }
}

static void read_all(int fd, void *buffer, size_t length)
{
    char *p = buffer;

    while (length > 0) {
        ssize_t count = read(fd, p, length);

        if (count < 0) {
            if (errno == EINTR)
                continue;
            die("read");
        }
        if (count == 0) {
            errno = EIO;
            die("unexpected end of file");
        }

        p += count;
        length -= (size_t)count;
    }
}

